def get_all_workflows() -> list[dict]:
    return WORKFLOWS


def workflow_lookup() -> dict[str, dict]:
    return {workflow["slug"]: workflow for workflow in WORKFLOWS}


def workflows_for_calculator(calculator_slug: str) -> list[dict]:
    return [
        workflow
        for workflow in WORKFLOWS
        if calculator_slug in workflow.get("calculator_slugs", [])
        or calculator_slug in workflow.get("additional_calculator_slugs", [])
    ]


def workflows_for_cluster(calculator_slugs: list[str]) -> list[dict]:
    calculator_set = set(calculator_slugs)
    return [
        workflow
        for workflow in WORKFLOWS
        if calculator_set.intersection(workflow.get("calculator_slugs", []))
        or calculator_set.intersection(workflow.get("additional_calculator_slugs", []))
    ]
